def solve_golomb(n, fixed_marks):
    # fixed_marks is a dictionary {index: value}
    marks = [0] * n
    for idx, val in fixed_marks.items():
        marks[idx] = val

    def backtrack(idx, current_marks):
        if idx == n:
            return current_marks

        # Start searching from the previous mark + 1
        start = current_marks[idx-1] + 1
        # A reasonable upper bound for an 8-mark Golomb ruler is 34 (the optimal is 34)
        for val in range(start, 40):
            new_marks = current_marks[:]
            new_marks[idx] = val

            # Check if the new mark maintains the Golomb property
            # Only need to check differences involving the new mark
            valid = True
            diffs = set()
            # Check all existing differences
            for i in range(idx + 1):
                for j in range(i + 1, idx + 1):
                    diff = new_marks[j] - new_marks[i]
                    if diff in diffs:
                        valid = False
                        break
                    diffs.add(diff)

            if valid:
                res = backtrack(idx + 1, new_marks)
                if res:
                    return res
        return None

    # Initial marks
    marks = [0] * n
    marks[0] = 0
    marks[1] = 2

    return backtrack(2, marks)

